   243		if err := repo.Storer.SetReference(newRef); err != nil {
   244			return fmt.Errorf("failed to update branch ref: %w", err)
   245		}
   246	
   247		// Clean up temp ref if we used one (best-effort, not critical if it fails)
   248		if isURL(target) {
