   255	// getMergeBase returns the merge base hash of two commits, or an error if they
   256	// have no common ancestor.
   257	func getMergeBase(ctx context.Context, repoPath, hashA, hashB string) (plumbing.Hash, error) {
   258		ctx, cancel := context.WithTimeout(ctx, 10*time.Second)
   259		defer cancel()
   260	
   261		cmd := exec.CommandContext(ctx, "git", "merge-base", hashA, hashB)
   262		cmd.Dir = repoPath
   263		output, err := cmd.Output()
   264		if err != nil {
   265			return plumbing.ZeroHash, fmt.Errorf("git merge-base failed: %w", err)
   266		}
   267	
   268		return plumbing.NewHash(strings.TrimSpace(string(output))), nil
   269	}
