   271	// collectCommitsSince walks from tip backwards (first parent only) and collects
   272	// commits until it reaches stopAt (exclusive). Returns commits oldest-first.
   273	func collectCommitsSince(repo *git.Repository, tip, stopAt plumbing.Hash) ([]*object.Commit, error) {
   274		var chain []*object.Commit
   275		current := tip
   276	
   277		for range MaxCommitTraversalDepth {
   278			if current == stopAt {
   279				break
   280			}
   281			commit, err := repo.CommitObject(current)
   282			if err != nil {
   283				return nil, fmt.Errorf("failed to get commit %s: %w", current, err)
   284			}
   285			chain = append(chain, commit)
   286	
   287			if len(commit.ParentHashes) == 0 {
   288				break
   289			}
   290			current = commit.ParentHashes[0]
   291		}
   292	
   293		// Reverse to oldest-first
   294		for i, j := 0, len(chain)-1; i < j; i, j = i+1, j-1 {
   295			chain[i], chain[j] = chain[j], chain[i]
   296		}
   297	
   298		return chain, nil
   299	}
