   301	// startProgressDots prints dots to w every second until the returned stop function
   302	// is called. The stop function prints the given suffix and a newline.
   303	func startProgressDots(w io.Writer) func(suffix string) {
   304		done := make(chan struct{})
   305		stopped := make(chan struct{})
   306		go func() {
   307			defer close(stopped)
   308			ticker := time.NewTicker(time.Second)
   309			defer ticker.Stop()
   310			for {
   311				select {
   312				case <-done:
   313					return
   314				case <-ticker.C:
   315					fmt.Fprint(w, ".")
   316				}
   317			}
   318		}()
   319		return func(suffix string) {
   320			close(done)
   321			<-stopped // Wait for goroutine to finish before writing suffix
   322			fmt.Fprintln(w, suffix)
   323		}
   324	}
